/**
 * Generate `src/assets.rs`: the compile-time asset table for a project.
 *
 * Two modes:
 *   - dev/build:  point at the Bun output dir (`dist`), one `include_bytes!`
 *                 per file, so `cargo build` embeds real bytes and never reads
 *                 the filesystem at runtime.
 *   - release:    identical, just a different directory.
 *
 * This file is generated, not hand-edited, and lives in the app crate. It is
 * the one codegen step in Kiln, and it is deliberately boring.
 */

import { existsSync, readdirSync, statSync } from "node:fs";
import { join, relative, sep } from "node:path";

const escape = (p: string) => p.replace(/\\/g, "\\\\").replace(/"/g, '\\"');

export function assetTable(
  outDir: string,
  assetsFileDir: string,
): { entries: number; source: string } {
  const files: string[] = [];

  if (!existsSync(outDir)) {
    return { entries: 0, source: emptyTable() };
  }

  const walk = (dir: string) => {
    for (const name of readdirSync(dir)) {
      const full = join(dir, name);
      if (statSync(full).isDirectory()) walk(full);
      else files.push(full);
    }
  };
  walk(outDir);
  files.sort();

  const lines = files.map((file) => {
    const key = relative(outDir, file).split(sep).join("/");
    const path = relative(assetsFileDir, file).split(sep).join("/");
    return `    ("${key}", include_bytes!("${escape(path)}")),`;
  });

  const source = `// @generated by kiln. Do not edit.
pub static ASSETS: kiln::AssetTable = &[
${lines.join("\n")}
];
`;

  return { entries: files.length, source };
}

function emptyTable(): string {
  return `// @generated by kiln. Do not edit.
pub static ASSETS: kiln::AssetTable = &[];
`;
}
